mapper.select:
select t.*,
       (select count(1) from proj_project p where p.contract_id = t.id and p.del_flag = '0') as project_count,
       (select count(1) from proj_payment pay
          inner join proj_project pj on pj.id = pay.project_id and pj.del_flag = '0'
          where pj.contract_id = t.id and pay.del_flag = '0') as paid_count,
       (select coalesce(sum(pay.amount), 0) from proj_payment pay
          inner join proj_project pj on pj.id = pay.project_id and pj.del_flag = '0'
          where pj.contract_id = t.id and pay.del_flag = '0') as paid_total
from (
select id, contract_no, contract_name, client_unit, contact_name, contact_phone,
       contract_type, contract_amount, sign_date, entrust_date, audit_date,
       return_date, finish_date, archive_date, archive_path, contract_period,
       payment_terms, received_amount, status, is_settled, extra_data::text as extra_data, del_flag,
       create_by, create_time, update_by, update_time, remark
from proj_contract
where del_flag = '0'

    AND contract_no like concat('%', #{contractNo}, '%')


    AND contract_name like concat('%', #{contractName}, '%')


    AND client_unit like concat('%', #{clientUnit}, '%')


    AND contract_type = #{contractType}


    AND contact_name like concat('%', #{contactName}, '%')


    AND status = #{status}


    AND (contract_no ilike concat('%', #{keyword}, '%')
         or contract_name ilike concat('%', #{keyword}, '%')
         or client_unit ilike concat('%', #{keyword}, '%')
         or contact_name ilike concat('%', #{keyword}, '%'))


    AND sign_date >= #{signDateBegin}


    AND sign_date <= #{signDateEnd}


    AND entrust_date >= #{entrustDateBegin}


    AND entrust_date <= #{entrustDateEnd}


    AND audit_date >= #{auditDateBegin}


    AND audit_date <= #{auditDateEnd}


    AND finish_date >= #{finishDateBegin}


    AND finish_date <= #{finishDateEnd}


    AND contract_amount >= #{contractAmountMin}


    AND contract_amount <= #{contractAmountMax}

) t
order by create_time desc

mapper.update:
update proj_contract
contract_no = #{contractNo}, contract_name = #{contractName}, client_unit = #{clientUnit}, contact_name = #{contactName}, contact_phone = #{contactPhone}, contract_type = #{contractType}, contract_amount = #{contractAmount}, sign_date = #{signDate}, entrust_date = #{entrustDate}, audit_date = #{auditDate}, return_date = #{returnDate}, finish_date = #{finishDate}, archive_date = #{archiveDate}, archive_path = #{archivePath}, contract_period = #{contractPeriod}, payment_terms = #{paymentTerms}, received_amount = #{receivedAmount}, status = #{status}, is_settled = #{isSettled}, extra_data = #{extraData}::jsonb, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where id = #{id}

mapper.select:
select distinct ${field}
from proj_contract
where del_flag = '0'
  and ${field} is not null
  and ${field} != ''
order by ${field}

select pj.contract_id as "contractId", pay.id as "paymentId", pay.amount as "amount", pay.pay_time as "payTime", pay.pay_unit as "payUnit", pay.payment_type as "paymentType", pj.id as "projectId", pj.project_name as "projectName", pj.project_code as "projectCode", pj.client_unit as "clientUnit", pj.contact_name as "contactName", pj.contact_phone as "contactPhone", pj.engineering_project as "engineeringProject", pj.project_location as "projectLocation" from proj_payment pay inner join proj_project pj on pj.id = pay.project_id and pj.del_flag = '0' where pay.del_flag = '0' and pj.contract_id in
#{cid}
order by pay.pay_time asc
